/**
 * get_filter_reference tool — detailed filter fields for a specific query.
 */
import { z } from 'zod';
export const getFilterReferenceSchema = z.object({
    query_name: z.string().max(200).describe('Name of a root GraphQL query (e.g. "transactions", "tokens", "nfts")'),
});
/** Queries that support list-style filtering */
function getListQueries(schema) {
    return schema.rootQueries.filter(q => q.isList);
}
function formatFilterFields(filterType, schema) {
    const lines = [];
    for (const field of filterType.fields) {
        const typeName = field.type.replace(/[!\[\]]/g, '');
        const isRange = typeName.endsWith('Range');
        let line = `  - \`${field.name}\`: \`${field.type}\``;
        if (field.description)
            line += ` — ${field.description}`;
        if (isRange)
            line += ' *(nested range object)*';
        lines.push(line);
        // Expand range sub-fields
        if (isRange) {
            const rangeType = schema.inputTypes.find(t => t.name === typeName);
            if (rangeType) {
                for (const rf of rangeType.fields) {
                    lines.push(`    - \`${rf.name}\`: \`${rf.type}\`${rf.description ? ` — ${rf.description}` : ''}`);
                }
            }
        }
    }
    return lines.join('\n');
}
function findFirstRangeField(filterType) {
    for (const field of filterType.fields) {
        const typeName = field.type.replace(/[!\[\]]/g, '');
        if (typeName === 'DateRange')
            return { fieldName: field.name, typeName };
        if (typeName === 'IntRange')
            return { fieldName: field.name, typeName };
    }
    return null;
}
export function handleGetFilterReference(input, schema) {
    if (!schema) {
        return 'Schema data not available. Data files may be missing — try reinstalling the package.';
    }
    const name = input.query_name.toLowerCase().trim();
    const query = schema.rootQueries.find(q => q.name.toLowerCase() === name);
    if (!query) {
        const available = schema.rootQueries.map(q => q.name).join(', ');
        return `Query "${input.query_name}" not found. Available root queries: ${available}`;
    }
    // Check if this query has a filter argument
    const filterArg = query.args.find(a => a.type.toLowerCase().includes('filter'));
    if (!filterArg) {
        const listQueryNames = getListQueries(schema).map(q => q.name).join(', ');
        return `The \`${query.name}\` query doesn't accept filters.\n\nQueries with filter support: ${listQueryNames}`;
    }
    const filterTypeName = filterArg.type.replace(/[!\[\]]/g, '');
    const filterType = schema.inputTypes.find(t => t.name === filterTypeName);
    if (!filterType) {
        return `Filter type \`${filterTypeName}\` referenced by \`${query.name}\` but not found in schema.`;
    }
    const fields = formatFilterFields(filterType, schema);
    // Build example using first range field
    const rangeField = findFirstRangeField(filterType);
    let example = '';
    if (rangeField) {
        if (rangeField.typeName === 'DateRange') {
            example = `

**Example — filter \`${query.name}\` by ${rangeField.fieldName}:**

\`\`\`graphql
query {
  ${query.name}(filter: { ${rangeField.fieldName}: { gte: "2024-01-01T00:00:00Z" } }, first: 5) {
    entries { ... }
    pageInfo { hasNextPage endCursor }
  }
}
\`\`\``;
        }
        else if (rangeField.typeName === 'IntRange') {
            example = `

**Example — filter \`${query.name}\` by ${rangeField.fieldName}:**

\`\`\`graphql
query {
  ${query.name}(filter: { ${rangeField.fieldName}: { gte: 1000000 } }, first: 5) {
    entries { ... }
    pageInfo { hasNextPage endCursor }
  }
}
\`\`\``;
        }
    }
    return `# Filters for \`${query.name}\`

**Filter type:** \`${filterTypeName}\`

**Fields:**
${fields}

## Range Operators

Range fields (\`DateRange\`, \`IntRange\`, etc.) accept a nested object with comparison operators:

| Operator | Meaning |
|----------|---------|
| \`eq\` | Equal to |
| \`gt\` | Greater than |
| \`gte\` | Greater than or equal |
| \`lt\` | Less than |
| \`lte\` | Less than or equal |

**Correct:** \`filter: { timestamp: { gte: "2024-01-01T00:00:00Z" } }\`
**Wrong:** \`filter: { timestampGte: "2024-01-01T00:00:00Z" }\` — flat suffixes don't work, use nested objects.${example}`;
}
